//! Rust chat search replays the TypeScript `searchMessagesInChat` vectors
//! (web_search_chats_ts_vectors.json, generated by chatSearchVectors.test.ts).
use crate::web_search::utf16_len;
use crate::web_search_chats::*;
use serde_json::{json, Value};

fn vectors() -> Value {
    serde_json::from_str(include_str!("web_search_chats_ts_vectors.json")).unwrap()
}

fn units(text: &str) -> Vec<u16> {
    text.encode_utf16().collect()
}

/// Decodes rows the way rustChatSearch.ts does, with snippets as UTF-16 units.
fn decode(rows: &[u32], entries: &[Value]) -> Value {
    assert!(
        rows.len() >= HEADER_WORDS,
        "one chat searched, one header expected"
    );
    assert_eq!(rows[0], 0);
    let (snippet_count, embed_count) = (rows[1] as usize, rows[2] as usize);
    assert_eq!(
        rows.len(),
        HEADER_WORDS + snippet_count * SNIPPET_WORDS + embed_count
    );
    let mut snippets = Vec::new();
    for row in
        rows[HEADER_WORDS..HEADER_WORDS + snippet_count * SNIPPET_WORDS].chunks(SNIPPET_WORDS)
    {
        let entry = &entries[row[0] as usize];
        let content = units(entry["content"].as_str().unwrap());
        let mut snippet: Vec<u16> = Vec::new();
        if row[3] & 1 != 0 {
            snippet.extend(units("... "));
        }
        snippet.extend_from_slice(&content[row[1] as usize..row[2] as usize]);
        if row[3] & 2 != 0 {
            snippet.extend(units(" ..."));
        }
        snippets.push((entry, snippet, row[4]));
    }
    let embeds: Vec<Value> = rows[rows.len() - embed_count..]
        .iter()
        .map(|&i| json!({"embedId": entries[i as usize]["embedId"], "messageId": entries[i as usize]["messageId"]}))
        .collect();
    json!({
        "snippets": snippets.into_iter().map(|(entry, snippet, start)| json!({
            "messageId": entry["messageId"],
            "embedId": entry.get("embedId").cloned().unwrap_or(Value::Null),
            "snippetUnits": snippet,
            "matchStart": start,
        })).collect::<Vec<_>>(),
        "embeds": embeds,
    })
}

#[test]
fn chat_search_equals_typescript() {
    let vectors = vectors();
    let mut index = ChatSearchIndex::default();
    let mut handles = std::collections::HashMap::new();
    for (n, (name, entries)) in vectors["chats"].as_object().unwrap().iter().enumerate() {
        let handle = n as u32 + 1;
        handles.insert(name.clone(), handle);
        index.reset_chat(handle);
        for entry in entries.as_array().unwrap() {
            let embed_id = entry["embedId"].as_str().unwrap_or("");
            let titled = !entry["embedTitle"].as_str().unwrap_or("").is_empty();
            index.push_entry(
                handle,
                entry["messageId"].as_str().unwrap(),
                entry["content"].as_str().unwrap(),
                embed_id,
                titled,
            );
        }
    }
    for case in vectors["cases"].as_array().unwrap() {
        let chat = case["chat"].as_str().unwrap();
        let query = case["query"].as_str().unwrap();
        let rows = index.search(
            query,
            &[handles[chat]],
            case["includeEmbeds"].as_bool().unwrap(),
        );
        let mut expected = case["expected"].clone();
        let length = utf16_len(query);
        for snippet in expected["snippets"].as_array_mut().unwrap() {
            assert_eq!(
                snippet["matchLength"].as_u64().unwrap() as usize,
                length,
                "{case}"
            );
            snippet.as_object_mut().unwrap().remove("matchLength");
        }
        let empty = expected["snippets"].as_array().unwrap().is_empty()
            && expected["embeds"].as_array().unwrap().is_empty();
        if empty {
            assert!(rows.is_empty(), "{case}");
            continue;
        }
        assert_eq!(
            decode(&rows, vectors["chats"][chat].as_array().unwrap()),
            expected,
            "{case}"
        );
    }
}

#[test]
fn chats_follow_handle_order_and_skip_unknown_or_removed_handles() {
    let mut index = ChatSearchIndex::default();
    index.reset_chat(7);
    index.push_entry(7, "a", "alpha needle", "", false);
    index.reset_chat(9);
    index.push_entry(9, "b", "beta needle", "", false);
    let rows = index.search("needle", &[9, 42, 7], false);
    assert_eq!(rows, vec![0, 1, 0, 0, 0, 11, 0, 5, 2, 1, 0, 0, 0, 12, 0, 6]);
    index.remove_chat(9);
    assert_eq!(index.search("needle", &[9, 7], false)[0], 1);
    index.reset_chat(7);
    assert_eq!(index.entry_count(7), 0);
    index.clear();
    assert_eq!(index.chat_count(), 0);
    assert!(index.search("", &[7], false).is_empty());
}
